<!-- wp:uagb/container {"block_id":"b6f64d1d","isBlockRootParent":true,"contentWidth":"alignfull","innerContentWidth":"alignwide","innerContentCustomWidthDesktop":1200,"directionDesktop":"row","directionTablet":"column","directionMobile":"column","alignItemsDesktop":"center","alignItemsTablet":"stretch","justifyContentDesktop":"space-between","wrapDesktop":"nowrap","topPaddingDesktop":64,"bottomPaddingDesktop":64,"leftPaddingDesktop":32,"rightPaddingDesktop":32,"topPaddingTablet":48,"bottomPaddingTablet":48,"leftPaddingTablet":32,"rightPaddingTablet":32,"topPaddingMobile":32,"bottomPaddingMobile":32,"leftPaddingMobile":24,"rightPaddingMobile":24,"paddingLink":false,"rowGapDesktop":48,"rowGapTablet":32,"rowGapMobile":24,"columnGapDesktop":48,"columnGapTablet":32,"columnGapMobile":24,"variationSelected":true,"backgroundType":"color","backgroundColor":"var(--wp--preset--color--quaternary)"} -->
