<div class="wp-block-uagb-container uagb-block-674d48f0">
<!-- wp:heading {"anchor":"time","style":{"spacing":{"margin":{"top":"0","bottom":"0"}}}} -->
<h2 id="time" class="wp-block-heading" style="margin-top:0;margin-bottom:0">It keeps your time.</h2>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0","bottom":"0"}}}} -->
<p style="margin-top:0;margin-bottom:0">The forest follows your real clock: dawn, midday, golden hour, dusk and night, with the sun and the moon where they should be. Play after supper and you&#039;ll need a lantern.</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0","bottom":"0"}}}} -->
<p style="margin-top:0;margin-bottom:0">Some of the forest changes with the seasons, too.</p>
<!-- /wp:paragraph -->
</div>
<!-- /wp:uagb/container -->
