<div class="wp-block-uagb-container uagb-block-462edf44">
<!-- wp:heading {"anchor":"content-levels","style":{"spacing":{"margin":{"top":"0","bottom":"0"}}}} -->
<h2 id="content-levels" class="wp-block-heading" style="margin-top:0;margin-bottom:0">Right for every player.</h2>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0","bottom":"0"}}}} -->
<p style="margin-top:0;margin-bottom:0">Each player has their own content level, from Little and Kid up to Adult. The Gnome keeps his words to the level of the player in front of him, and a grown-up decides how rough the forest is allowed to get.</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0","bottom":"0"}}},"textColor":"neutral","fontSize":"small"} -->
<p class="has-neutral-color has-text-color has-small-font-size" style="margin-top:0;margin-bottom:0">A grown-up adds the players, sets their levels and chooses who may type to the Gnome, all from the game&#039;s settings page.</p>
<!-- /wp:paragraph -->
</div>
<!-- /wp:uagb/container -->
